/**
 * Backend data access for the composer sticker / GIF picker.
 *
 * The round-2 kernel service exposes `GetStickerPacks`, `GetStickerSet` and
 * `GetSavedGifs`; the generated Wails bindings under `frontend/bindings/**` are
 * regenerated by backend2 after this frontend lands. To keep `tsc` green in the
 * meantime (and to tolerate the DTO class shapes Wails generates) the service
 * namespace is cast through a *local*, structurally typed interface instead of
 * importing generated DTO types. Once the bindings exist this file needs no
 * change: the casts are only compile-time.
 *
 * Caching model (mirrors the kernel cache plan in
 * temp/research2/stickers-gifs.md §5.5 / §7.2):
 *   - packs: 60 s, dropped after a send and on a failed send;
 *   - set details: 30 min (documents rarely change), shared per set ref;
 *   - saved GIFs: 60 s.
 * Module-level promise caches dedupe concurrent mounts (rail + section open at
 * the same moment) and survive tab switches, so re-opening a tab paints from
 * cache instantly.
 *
 * "Refresh after send" has two halves:
 *   1. optimistic local state - the sent sticker is promoted into the Recent
 *      row (Telegram does not add it server-side; the client is responsible),
 *      and a sent saved GIF moves to the front of the grid (the server reorders
 *      its own saved list and later pushes UpdateSavedGifs);
 *   2. staleness - the affected cache entry is marked stale so the next panel
 *      open refetches from the kernel, which returns fresh opaque doc refs
 *      (file references expire). A failed send additionally drops the entries
 *      and notifies mounted tabs to refetch immediately, because the most
 *      likely cause is an expired/blocked document ref.
 */
import { Service as AppService } from "../../bindings/tgdesk/internal/app";
import type {
  SavedGif,
  StickerDoc,
  StickerPacks,
  StickerSetDetail,
} from "../types";

/** Transport settings the kernel RPCs need (same pair App passes elsewhere). */
export interface PickerNetwork {
  proxy: string;
  ntp: string;
}

const RECENT_LIMIT = 20;
const PACKS_TTL_MS = 60_000;
const SET_TTL_MS = 30 * 60_000;
const GIFS_TTL_MS = 60_000;

/**
 * Loose payload shapes on purpose: the generated bindings wrap the kernel DTOs
 * in classes, and the kernel may return `null` for an empty/failed read.
 */
interface StickerPacksPayload {
  recent?: StickerDoc[] | null;
  sets?: StickerPacks["sets"] | null;
}

interface StickerSetDetailPayload {
  set?: StickerSetDetail["set"] | null;
  stickers?: StickerDoc[] | null;
}

type SavedGifsPayload = SavedGif[] | { gifs?: SavedGif[] | null } | null;

/**
 * The future generated service surface. `$CancellablePromise<T>` returned by
 * Wails is a `Promise<T>` subtype, so `Promise<T>` is correct here and the cast
 * below bridges the gap until the bindings are regenerated.
 */
export interface StickerBindings {
  GetStickerPacks(proxy: string, ntp: string): Promise<StickerPacksPayload | null>;
  GetStickerSet(
    ref: string,
    proxy: string,
    ntp: string,
  ): Promise<StickerSetDetailPayload | null>;
  GetSavedGifs(proxy: string, ntp: string): Promise<SavedGifsPayload>;
}

const bindings = AppService as unknown as StickerBindings;

// ------------------------------------------------------------------- caches

interface CacheEntry<T> {
  at: number;
  value?: T;
  promise?: Promise<T>;
}

const packsCache = new Map<string, CacheEntry<StickerPacks>>();
const setCache = new Map<string, CacheEntry<StickerSetDetail>>();
const gifsCache = new Map<string, CacheEntry<SavedGif[]>>();

/** Client-side recent stickers per account (Telegram leaves this to the client). */
const localRecentStickers = new Map<string, StickerDoc[]>();
/** Client-side saved-GIF order per account (moves a sent GIF to the front). */
const localGifOrder = new Map<string, string[]>();

export function networkKey(network: PickerNetwork): string {
  return `${network.proxy}\u0000${network.ntp}`;
}

// --------------------------------------------------------------- normalisers

function mergeRecent(key: string, serverRecent: readonly StickerDoc[]): StickerDoc[] {
  const seen = new Set<string>();
  const result: StickerDoc[] = [];
  const push = (doc: StickerDoc | undefined) => {
    if (!doc?.id || seen.has(doc.id) || result.length >= RECENT_LIMIT) {
      return;
    }
    seen.add(doc.id);
    result.push(doc);
  };
  for (const doc of localRecentStickers.get(key) ?? []) {
    push(doc);
  }
  for (const doc of serverRecent) {
    push(doc);
  }
  return result;
}

function normalizePacks(
  payload: StickerPacksPayload | null,
  key: string,
): StickerPacks {
  const recent = mergeRecent(key, payload?.recent ?? []);
  const sets = (payload?.sets ?? []).filter(
    (set): set is StickerPacks["sets"][number] =>
      Boolean(set && typeof set.ref === "string" && set.ref.length > 0),
  );
  return { recent, sets };
}

function normalizeSetDetail(
  payload: StickerSetDetailPayload | null,
  ref: string,
): StickerSetDetail | null {
  if (!payload) {
    return null;
  }
  const stickers = (payload.stickers ?? []).filter(
    (doc): doc is StickerDoc =>
      Boolean(doc && typeof doc.ref === "string" && doc.ref.length > 0),
  );
  const set = payload.set ?? null;
  if (!set) {
    return null;
  }
  return { set, stickers };
}

function normalizeGifs(payload: SavedGifsPayload, key: string): SavedGif[] {
  const raw = Array.isArray(payload) ? payload : (payload?.gifs ?? []);
  const gifs = raw.filter(
    (gif): gif is SavedGif =>
      Boolean(gif && typeof gif.ref === "string" && gif.ref.length > 0),
  );
  const order = localGifOrder.get(key);
  if (!order || order.length === 0) {
    return gifs;
  }
  const rank = new Map(order.map((ref, index) => [ref, index]));
  // Stable in modern engines: entries absent from the local order keep their
  // server relative order after the promoted ones.
  return gifs
    .map((gif, index) => ({ gif, index }))
    .sort((left, right) => {
      const leftRank = rank.get(left.gif.ref) ?? Number.POSITIVE_INFINITY;
      const rightRank = rank.get(right.gif.ref) ?? Number.POSITIVE_INFINITY;
      return leftRank === rightRank
        ? left.index - right.index
        : leftRank < rightRank
          ? -1
          : 1;
    })
    .map((entry) => entry.gif);
}

// ------------------------------------------------------------- cache loading

function loadCached<T>(
  cache: Map<string, CacheEntry<T>>,
  key: string,
  ttlMs: number,
  force: boolean,
  fetch: (entry: CacheEntry<T>) => Promise<T>,
): Promise<T> {
  let entry = cache.get(key);
  if (!entry) {
    entry = { at: 0 };
    cache.set(key, entry);
  }
  if (!force && entry.value !== undefined && Date.now() - entry.at < ttlMs) {
    return Promise.resolve(entry.value);
  }
  if (entry.promise) {
    return entry.promise;
  }
  const promise = fetch(entry).then(
    (value) => {
      if (entry) {
        entry.promise = undefined;
      }
      return value;
    },
    (error: unknown) => {
      if (entry) {
        entry.promise = undefined;
        entry.at = 0;
      }
      throw error;
    },
  );
  entry.promise = promise;
  return promise;
}

async function fetchStickerPacks(
  network: PickerNetwork,
  key: string,
  entry: CacheEntry<StickerPacks>,
): Promise<StickerPacks> {
  const payload = await bindings.GetStickerPacks(network.proxy, network.ntp);
  const packs = normalizePacks(payload, key);
  entry.value = packs;
  entry.at = Date.now();
  return packs;
}

async function fetchStickerSet(
  network: PickerNetwork,
  ref: string,
  entry: CacheEntry<StickerSetDetail>,
): Promise<StickerSetDetail> {
  const payload = await bindings.GetStickerSet(ref, network.proxy, network.ntp);
  const detail = normalizeSetDetail(payload, ref);
  if (!detail) {
    throw new Error("sticker set response is empty");
  }
  entry.value = detail;
  entry.at = Date.now();
  return detail;
}

async function fetchSavedGifs(
  network: PickerNetwork,
  key: string,
  entry: CacheEntry<SavedGif[]>,
): Promise<SavedGif[]> {
  const payload = await bindings.GetSavedGifs(network.proxy, network.ntp);
  const gifs = normalizeGifs(payload, key);
  entry.value = gifs;
  entry.at = Date.now();
  return gifs;
}

// --------------------------------------------------------------- public reads

export function peekStickerPacks(network: PickerNetwork): StickerPacks | undefined {
  return packsCache.get(networkKey(network))?.value;
}

export function loadStickerPacks(
  network: PickerNetwork,
  options: { force?: boolean } = {},
): Promise<StickerPacks> {
  const key = networkKey(network);
  return loadCached(packsCache, key, PACKS_TTL_MS, options.force === true, (entry) =>
    fetchStickerPacks(network, key, entry),
  );
}

export function peekStickerSet(
  network: PickerNetwork,
  ref: string,
): StickerSetDetail | undefined {
  return setCache.get(`${networkKey(network)}\u0000${ref}`)?.value;
}

export function loadStickerSet(
  network: PickerNetwork,
  ref: string,
  options: { force?: boolean } = {},
): Promise<StickerSetDetail> {
  const key = `${networkKey(network)}\u0000${ref}`;
  return loadCached(setCache, key, SET_TTL_MS, options.force === true, (entry) =>
    fetchStickerSet(network, ref, entry),
  );
}

export function peekSavedGifs(network: PickerNetwork): SavedGif[] | undefined {
  return gifsCache.get(networkKey(network))?.value;
}

export function loadSavedGifs(
  network: PickerNetwork,
  options: { force?: boolean } = {},
): Promise<SavedGif[]> {
  const key = networkKey(network);
  return loadCached(gifsCache, key, GIFS_TTL_MS, options.force === true, (entry) =>
    fetchSavedGifs(network, key, entry),
  );
}

// ------------------------------------------------------------ cache watching

export interface StickerCacheChange {
  /**
   * True when consumers should refetch from the kernel right away (cache was
   * dropped after a failure); false for optimistic local updates.
   */
  force: boolean;
}

type StickerCacheListener = (change: StickerCacheChange) => void;

const listeners = new Set<StickerCacheListener>();

export function subscribeStickerCache(listener: StickerCacheListener): () => void {
  listeners.add(listener);
  return () => {
    listeners.delete(listener);
  };
}

function notify(change: StickerCacheChange): void {
  for (const listener of Array.from(listeners)) {
    try {
      listener(change);
    } catch {
      // A listener must never break another tab's update.
    }
  }
}

/** Drops every cached response but keeps the optimistic recent/GIF order. */
export function invalidateStickerCaches(): void {
  packsCache.clear();
  setCache.clear();
  gifsCache.clear();
  notify({ force: true });
}

// ------------------------------------------------------ refresh after a send

/**
 * Promotes a sent sticker into the Recent row, marks the packs cache stale so
 * the next open refetches fresh document refs, and updates mounted tabs.
 */
export function noteStickerSent(network: PickerNetwork, doc: StickerDoc): void {
  const key = networkKey(network);
  const previous = localRecentStickers.get(key) ?? [];
  localRecentStickers.set(
    key,
    [doc, ...previous.filter((item) => item.id !== doc.id)].slice(0, RECENT_LIMIT),
  );
  const entry = packsCache.get(key);
  if (entry?.value) {
    entry.value = {
      recent: mergeRecent(key, entry.value.recent),
      sets: entry.value.sets,
    };
    // Stale for the *next* load (fresh file references) but visually current.
    entry.at = 0;
  }
  notify({ force: false });
}

/**
 * Moves a sent GIF to the front of the saved-GIF grid and marks the cache stale
 * so the next open refetches from the kernel (the server reorders saved GIFs on
 * use and pushes UpdateSavedGifs).
 */
export function noteGifSent(network: PickerNetwork, gif: SavedGif): void {
  const key = networkKey(network);
  const previous = localGifOrder.get(key) ?? [];
  localGifOrder.set(
    key,
    [gif.ref, ...previous.filter((ref) => ref !== gif.ref)].slice(0, 200),
  );
  const entry = gifsCache.get(key);
  if (entry?.value) {
    entry.value = [gif, ...entry.value.filter((item) => item.ref !== gif.ref)];
    entry.at = 0;
  }
  notify({ force: false });
}

/**
 * Called when a send fails: the most likely cause is an expired document ref /
 * file reference, so drop the caches for this account and ask mounted tabs to
 * refetch immediately. `setCache` entries for the account are dropped too so a
 * lazy section reload gets fresh sticker documents.
 */
export function refreshStickerDataAfterSendFailure(network: PickerNetwork): void {
  const key = networkKey(network);
  packsCache.delete(key);
  gifsCache.delete(key);
  const prefix = `${key}\u0000`;
  for (const cacheKey of Array.from(setCache.keys())) {
    if (cacheKey.startsWith(prefix)) {
      setCache.delete(cacheKey);
    }
  }
  notify({ force: true });
}

/** Test/preview seam: forget every module-level cache and optimistic state. */
export function resetStickerCaches(): void {
  packsCache.clear();
  setCache.clear();
  gifsCache.clear();
  localRecentStickers.clear();
  localGifOrder.clear();
  notify({ force: true });
}
